        "raw": "आप जैसों के लिए इस में रखा कुछ भी नहीं, लेकिन ऐसे तो न कहिए कि वफ़ा कुछ भी नहीं। \nआप कहिए तो निभाते चले जाएँगे मगर, इस ताल्लुक़ में अज़ियत के सिवा कुछ भी नहीं।\nमैं किसी तरह से भी समझौता नहीं कर सकता, या तो सब कुछ ही मुझे चाहिए या कुछ भी नहीं। \nकैसे जाना है, कहाँ जाना है, क्यों जाना है, हम कि चलते चले जाते हैं पता कुछ भी नहीं।\nअब क्या मैं अपनी मोहब्बत का भरम भी न रखूँ, मान लेता हूँ उस शख़्स में था कुछ भी नहीं। \nमैंने दुनिया से अलग रह कर भी देखा 'जवाद', ऐसी महज़ूर उदासी की दवा कुछ भी नहीं।",
